pub fn ensure_seeded() -> Result<(), StorageError> {
    let repo = FileGameRepository;
    
    if repo.get_game_count()? == 0 {
        let games: Vec<GameInfo> = GAMES_DATA.iter()
            .map(|(id, name, developer, publisher, release_date, genres)| GameInfo {
                id: id.to_string(),
                name: name.to_string(),
                cover_url: String::new(),
                developer: developer.to_string(),
                publisher: publisher.to_string(),
                release_date: Some(release_date.to_string()),
                genres: genres.iter().map(|s| s.to_string()).collect(),
            })
            .collect();
        
        repo.insert_games(&games)?;
        
        let requirements_repo = FileRequirementsRepository;
        let reqs: Vec<GameRequirements> = REQUIREMENTS_DATA.iter()
            .map(|(game_id, min_cpu, min_cpu_cores, min_cpu_freq, min_gpu, min_gpu_mem, min_mem, min_storage, min_os, rec_cpu, rec_cpu_cores, rec_cpu_freq, rec_gpu, rec_gpu_mem, rec_mem, rec_storage, rec_os)| GameRequirements {
                game_id: game_id.to_string(),
                minimum: Requirement {
                    cpu: min_cpu.to_string(),
                    cpu_core_count: Some(*min_cpu_cores),
                    cpu_frequency: Some(*min_cpu_freq),
                    gpu: min_gpu.to_string(),
                    gpu_memory: Some(*min_gpu_mem),
                    memory: *min_mem,
                    storage: *min_storage,
                    os: min_os.to_string(),
                },
                recommended: Requirement {
                    cpu: rec_cpu.to_string(),
                    cpu_core_count: Some(*rec_cpu_cores),
                    cpu_frequency: Some(*rec_cpu_freq),
                    gpu: rec_gpu.to_string(),
                    gpu_memory: Some(*rec_gpu_mem),
                    memory: *rec_mem,
                    storage: *rec_storage,
                    os: rec_os.to_string(),
                },
            })
            .collect();
        
        requirements_repo.insert_requirements_batch(&reqs)?;
    }
    
    Ok(())
}